using System;
using System.Threading;
using System.Threading.Tasks;

// PROGRAM: Pembuktian Race Condition vs Operasi Atomik Interlocked
int unsafeCounter = 0;
int atomicCounter = 0;

const int Target = 100_000;

var tasks = new Task[10];
for (int t = 0; t < tasks.Length; t++)
{
    tasks[t] = Task.Run(() => {
        for (int i = 0; i < Target; i++)
        {
            unsafeCounter++; // Tidak aman! (Data Race)
            Interlocked.Increment(ref atomicCounter); // Aman 100% (Hardware Atomic)
        }
    });
}

Task.WaitAll(tasks);

int expected = Target * tasks.Length;
Console.WriteLine($"Target Seharusnya : {expected:N0}");
Console.WriteLine($"Unsafe Counter    : {unsafeCounter:N0} (Selisih Korup: {expected - unsafeCounter:N0})");
Console.WriteLine($"Atomic Counter    : {atomicCounter:N0} (Akurat 100%!)");

