using System;
using System.Threading;

public class LockFreeMetricAccumulator
{
    private long _totalValue;

    public void Add(long amount)
    {
        Interlocked.Add(ref _totalValue, amount);
    }

    public long GetValue()
    {
        return Interlocked.Read(ref _totalValue);
    }
}

public class Program
{
    public static void Main()
    {
        var acc = new LockFreeMetricAccumulator();
        acc.Add(100);
        acc.Add(250);
        Console.WriteLine($"Total: {acc.GetValue()}");
    }
}
